import test from 'node:test';
import assert from 'node:assert/strict';
import { PokerAudio } from './audio.js';
function context(){return {state:'suspended',currentTime:0,destination:{},started:0,stopped:0,resume(){this.state='running';return Promise.resolve();},close(){this.state='closed';return Promise.resolve();},createGain(){return {gain:{value:1},connect(){}};},decodeAudioData(){return Promise.resolve({duration:0.1});},createBufferSource(){const ctx=this;return {connect(){},disconnect(){},start(){ctx.started++;},stop(){ctx.stopped++;this.onended?.();}};}};}
const response=()=>Promise.resolve({ok:true,arrayBuffer:async()=>new ArrayBuffer(4)});
test('stop cancels sounds still loading',async()=>{const ctx=context();let resolve,loaded;const loading=new Promise(r=>loaded=r);const a=new PokerAudio({contextFactory:()=>ctx,fetchImpl:()=>new Promise(r=>{resolve=r;loaded();}),documentImpl:null});await a.unlock();const play=a.play('deal');await loading;a.stop();resolve({ok:true,arrayBuffer:async()=>new ArrayBuffer(4)});await play;assert.equal(ctx.started,0);a.close();});
test('mute ends sources and cannot start a pending sequence',async()=>{const ctx=context();const a=new PokerAudio({contextFactory:()=>ctx,fetchImpl:response,documentImpl:null});await a.unlock();await a.play('deal');assert.equal(ctx.started,1);a.sequence([{at:50,name:'hold'}]);a.configure({soundEnabled:false,volume:0.4});await new Promise(r=>setTimeout(r,80));assert.equal(ctx.started,1);assert.equal(ctx.stopped,1);await a.play('hold');assert.equal(ctx.started,1);a.close();});
test('leaving page stops audio and returning does not replay it',async()=>{const ctx=context(),doc=new EventTarget();doc.hidden=false;const a=new PokerAudio({contextFactory:()=>ctx,fetchImpl:response,documentImpl:doc});await a.unlock();await a.play('deal');doc.hidden=true;doc.dispatchEvent(new Event('visibilitychange'));assert.equal(ctx.stopped,1);doc.hidden=false;doc.dispatchEvent(new Event('visibilitychange'));assert.equal(ctx.started,1);a.close();});
test('audio loading failure is explicit but retry works',async()=>{const ctx=context();let fail=true;const a=new PokerAudio({contextFactory:()=>ctx,fetchImpl:()=>fail?Promise.reject(Error('offline')):response(),documentImpl:null});await a.unlock();assert.equal(await a.play('deal'),false);fail=false;assert.equal(await a.play('deal'),true);assert.equal(ctx.started,1);a.close();});
test('late decoded card sounds are skipped instead of bunching after reveal',async()=>{const ctx=context();ctx.currentTime=2;const a=new PokerAudio({contextFactory:()=>ctx,fetchImpl:response,documentImpl:null});await a.unlock();assert.equal(await a.play('deal',{when:1}),false);assert.equal(ctx.started,0);a.close();});
test('preparation has a time limit when a sound request stalls',async()=>{const ctx=context();const a=new PokerAudio({contextFactory:()=>ctx,fetchImpl:()=>new Promise(()=>{}),documentImpl:null});assert.equal(await a.prepare(['deal'],15),false);a.close();});
test('warming is sequential and leaving prevents queued requests',async()=>{const ctx=context();let finish,calls=0;const a=new PokerAudio({contextFactory:()=>ctx,documentImpl:null,fetchImpl:()=>{calls++;return new Promise(resolve=>{finish=resolve;});}});await a.unlock();const warmed=a.warm();assert.equal(calls,1);a.warm();assert.equal(calls,1);a.close();finish({ok:true,arrayBuffer:async()=>new ArrayBuffer(4)});await warmed;assert.equal(calls,1);});
